#ifdef TOON_ADD
  {
    // additive glow: coverage (clamped brightness x alpha) picks the band,
    // so wide soft halos shrink to their core instead of filling the screen
    float _m = max(max(gl_FragColor.r, gl_FragColor.g), gl_FragColor.b);
    float _i = min(_m, 1.0) * gl_FragColor.a;
    if (_i < 0.4) discard;
    vec3 _h = gl_FragColor.rgb / max(_m, 1e-4);
    vec3 _c = _i < 0.48 ? vec3(0.015, 0.015, 0.02)
            : _i < 0.65 ? _h * 0.72
            : _i < 0.85 ? _h * 0.9
            : mix(_h, vec3(1.0), _m * gl_FragColor.a > 1.6 ? 0.65 : 0.2);
    gl_FragColor = vec4(_c, 1.0);
  }
#else
  if (gl_FragColor.a < 0.5) discard;
  gl_FragColor = vec4(floor(gl_FragColor.rgb * 5.0 + 0.5) / 5.0, 1.0);
#endif

glsl.puppetHead:
uniform vec3 uPinP[8], uPinD[8];
uniform int uPinN;
uniform float uPinR;
// normalised gaussian blend: pins left in place hold the shape around them
vec3 nfPuppet(vec3 w) {
  vec3 sum = vec3(0.0); float ws = 0.0;
  for (int i = 0; i < 8; i++) {
    if (i >= uPinN) break;
    vec3 d = w - uPinP[i];
    float g = exp(-dot(d, d) / (uPinR * uPinR) * 3.0);
    sum += uPinD[i] * g; ws += g;
  }
  return w + sum / max(1.0, ws);
}

glsl.puppetTail:
if (uPinN > 0) {
  mat4 nfVP = projectionMatrix * viewMatrix;
  vec4 nfW = inverse(nfVP) * gl_Position;
  gl_Position = nfVP * vec4(nfPuppet(nfW.xyz / nfW.w), 1.0);
}

