shaders.fragment:
float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123); }
float vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
return mix(mix(hash(i),hash(i+vec2(1,0)),f.x), mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x), f.y); }
float fbm2(vec2 p){ float s=0.0, a=0.5; for(int i=0;i<4;i++){ s+=a*vnoise(p); p*=2.03; a*=0.5; } return s; }
uniform float uStyle,uTime,uAlpha,uGlow,uWobble,uCenter,uSeed; uniform vec3 uPal[5]; varying vec2 vUv;
vec2 hash2(vec2 p){ return fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3))))*43758.5453); }
vec3 voro(vec2 x){ vec2 n=floor(x), f=fract(x); float d1=8.0, d2=8.0; vec2 id=vec2(0.0);
for(int j=-1;j<=1;j++) for(int i=-1;i<=1;i++){ vec2 g=vec2(float(i),float(j)); vec2 o=hash2(n+g); o=0.5+0.4*sin(uTime*0.8+6.2831*o);
  vec2 r=g+o-f; float d=dot(r,r); if(d<d1){ d2=d1; d1=d; id=n+g; } else if(d<d2) d2=d; }
return vec3(sqrt(d2)-sqrt(d1), hash(id), sqrt(d1)); }
void main(){
vec2 p=(vUv-0.5)*2.2; float r=length(p); float ang=atan(p.y,p.x);
float R=0.9 + (vnoise(vec2(ang*2.5+uSeed, uTime*0.6))-0.5)*0.16*uWobble + sin(ang*14.0)*0.012*uWobble;
if (r > R+0.08) discard;
float edge=1.0-smoothstep(R, R+0.07, r);
vec3 col=uPal[1]; float a=1.0; float hot=0.0;
int st=int(uStyle+0.5);
if (st==0) {
  float tw=ang + r*5.0 - uTime*2.2;
  float k=fbm2(vec2(cos(tw),sin(tw))*2.0 + vec2(r*4.0 - uTime*0.6)) + r*0.45;
  if (k<0.55) col=uPal[0]; else if (k<0.75) col=uPal[1]; else if (k<0.9) { col=uPal[2]; hot=0.6; } else { col=uPal[3]; hot=1.0; }
  a=mix(0.75,1.0,smoothstep(0.2,0.6,r));
} else if (st==1) {
  float n=fbm2(p*3.0 + vec2(uTime*0.4,-uTime*0.3));
  float line=abs(sin(n*14.0 + uTime*1.5));
  col=mix(uPal[1],uPal[2],smoothstep(0.0,0.9,r));
  if (line<0.12) { col=uPal[3]; hot=0.8; }
  a=0.85;
} else if (st==2) {
  vec3 v=voro(p*4.0);
  col=mix(uPal[0],uPal[1],smoothstep(0.0,0.6,r));
  if (v.y>0.45 && v.z<0.38) { col=uPal[2]; hot=0.6; }
  if (v.x<0.05) col=mix(col,uPal[3],0.5);
  a=0.9;
} else if (st==3) {
  float n=fbm2(p*3.2 + vec2(0.0,-uTime*1.2)) + 0.25*(1.0-r);
  if (n<0.45) { col=uPal[0]; a=0.75; } else if (n<0.58) col=uPal[1]; else if (n<0.7) { col=uPal[2]; hot=0.7; } else { col=uPal[3]; hot=1.0; }
} else if (st==4) {
  vec3 v=voro(p*5.0+0.3);
  col=mix(uPal[0],uPal[1],fbm2(p*4.0));
  if (v.x<0.06) { col=uPal[3]; hot=0.8; }
  float rays=smoothstep(0.6,1.0,r)*(0.5+0.5*sin(ang*90.0 + vnoise(vec2(ang*20.0,0.0))*6.0));
  col=mix(col,uPal[3],rays*0.6); hot=max(hot,rays*0.6);
  a=0.85;
} else if (st==5) {
  col=uPal[0]; a=0.7;
} else {
  float n=fbm2(p*2.5 + uTime*0.15);
  col=mix(uPal[0],uPal[1],smoothstep(0.35,0.7,n)); col=mix(col,uPal[2],smoothstep(0.6,0.85,n));
  float s=step(0.985, hash(floor(p*60.0))); col=mix(col,uPal[4],s); hot=max(hot,s);
  a=0.95;
}
float rimLine=smoothstep(R-0.03,R-0.008,r)*edge, rimBand=0.22*smoothstep(R-0.16,R-0.03,r)*edge;
col=mix(col,uPal[3],rimBand); col=mix(col,uPal[4],rimLine); hot=max(hot,max(rimLine,rimBand));
float cg=uCenter*exp(-r*r*14.0); col+=uPal[4]*cg; hot=max(hot,cg);
col*=mix(1.0,uGlow,hot);
gl_FragColor=vec4(col, a*edge*uAlpha);
}
